using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps customers rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryCustomerRepository : ICustomerRepository
{
    private readonly Dictionary<string, Customer> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Customer row) => [row.Id];

    private static string KeyText(Customer row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Customer> Visible() =>
        rows.Values.Where(row => row.DeletedAt == null).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Customer?> FindByIdAsync(string id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Customer>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Customer>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Customer?> FindByEmailAsync(string email)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Email, email)));
    }

    public Task<Customer> InsertAsync(Customer entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        entity.Active ??= true;
        entity.Level ??= "basic";
        entity.CreatedAt ??= DateTime.UtcNow;
        entity.UpdatedAt ??= DateTime.UtcNow;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Customer> UpdateAsync(Customer entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Customer entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }

    public Task<Customer?> AddTagAsync(string id, string tag)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null) return Task.FromResult<Customer?>(null);
        found.Tags = [..found.Tags ?? [], tag];
        found.UpdatedAt = DateTime.UtcNow;
