using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on countries. Repositories commit every write.</summary>
public class CountryService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "countries" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Country? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("DocumentId");
            if (value is null)
                if (creating || values.ContainsKey("DocumentId")) errors.Add(new FieldError("_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Id");
            if (value is null)
                if (creating || values.ContainsKey("Id")) errors.Add(new FieldError("id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Name");
            if (value is null)
                if (creating || values.ContainsKey("Name")) errors.Add(new FieldError("name", "is required"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Country", errors);
    }

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Country? current)
    {
        {
            var id = values.TryGetValue("Id", out var givenId) ? (double?)givenId : current?.Id;
            if (id is not null)
            {
                var other = await uow.Countries.FindByIdAsync(id.Value);
                if (other is not null && (current is null || !Equals(other.DocumentId, current.DocumentId)))
                    throw new ConflictException("Country", "id is already taken", ["Id"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Country? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
