            if (value is not null)
            {
                if (!(Number(value) >= 0m)) errors.Add(new FieldError("stock", "must be >= 0"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Product", errors);
    }

    /// <summary>A number of any type, to compare it.</summary>
    private static decimal Number(object value) => Convert.ToDecimal(value, CultureInfo.InvariantCulture);

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Product? current)
    {
        {
            var sku = values.TryGetValue("Sku", out var givenSku) ? (string?)givenSku : current?.Sku;
            if (sku is not null)
            {
                var other = await uow.Products.FindBySkuAsync(sku);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Product", "sku is already taken", ["Sku"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Product? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Product entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Sku", out var sku)) entity.Sku = (string)sku!;
        if (values.TryGetValue("Title", out var title)) entity.Title = (string)title!;
        if (values.TryGetValue("Price", out var price)) entity.Price = (decimal)price!;
        if (values.TryGetValue("Stock", out var stock)) entity.Stock = (double?)stock;
        if (values.TryGetValue("Reference", out var reference)) entity.Reference = (Guid?)reference;
        if (values.TryGetValue("Picture", out var picture)) entity.Picture = (byte[]?)picture;
        if (values.TryGetValue("Related", out var related)) entity.Related = (List<string>?)related;
    }

    /// <summary>The Product with this key; NotFoundException when there is none.</summary>
    private static async Task<Product> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Products.FindByIdAsync(id) ?? throw new NotFoundException("Product", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(ProductChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Sku is { IsPresent: true } sku) values["Sku"] = sku.Value;
        if (changes.Title is { IsPresent: true } title) values["Title"] = title.Value;
        if (changes.Price is { IsPresent: true } price) values["Price"] = price.Value;
        if (changes.Stock is { IsPresent: true } stock) values["Stock"] = stock.Value;
        if (changes.Reference is { IsPresent: true } reference) values["Reference"] = reference.Value;
        if (changes.Picture is { IsPresent: true } picture) values["Picture"] = picture.Value;
        if (changes.Related is { IsPresent: true } related) values["Related"] = related.Value;
        return values;
    }

    /// <summary>Stores a new Product after checking it.</summary>
    public async Task<Product> CreateProductAsync(Product product)
    {
        var values = new Dictionary<string, object?>();
        if (product.Sku is not null) values["Sku"] = product.Sku;
        if (product.Title is not null) values["Title"] = product.Title;
        values["Price"] = product.Price;
        if (product.Stock is not null) values["Stock"] = product.Stock;
        if (product.Reference is not null) values["Reference"] = product.Reference;
        if (product.Picture is not null) values["Picture"] = product.Picture;
        if (product.Related is not null) values["Related"] = product.Related;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Products.InsertAsync(product);
        });
    }

    /// <summary>The Product with this key; NotFoundException when there is none.</summary>
    public async Task<Product> GetProductAsync(string id) => await FindAsync(uow, id);

    /// <summary>A page of products, by primary key.</summary>
    public async Task<Page<Product>> ListProductsAsync(int offset, int limit) => await uow.Products.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Product.</summary>
    public async Task<Product> UpdateProductAsync(string id, ProductChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Products.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Product.</summary>
    public async Task DeleteProductAsync(string id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Products.DeleteAsync(current);
        });
    }

    /// <summary>The Product with this sku, or null.</summary>
    public async Task<Product?> FindProductBySkuAsync(string sku) => await uow.Products.FindBySkuAsync(sku);

    /// <summary>Adds an item to related.</summary>
    public async Task<Product> AddRelatedAsync(string id, string related)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Products.AddRelatedAsync(id, related) ?? throw new NotFoundException("Product", id);
        });
    }

    /// <summary>Removes an item from related, by its value.</summary>
    public async Task<Product> RemoveRelatedAsync(string id, string related)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (current.Related is null || !current.Related.Contains(related)) throw new NotFoundException("Related", related);
            return await uow.Products.RemoveRelatedAsync(id, related) ?? throw new NotFoundException("Product", id);
        });
    }
}

