using App;
using App.Common;
using App.Entities;
using App.Errors;
using App.Services;
using Xunit;

namespace App.Tests;

/// <summary>The repository of the "products" table, against the test database.</summary>
public class ProductRepositoryTests : IAsyncLifetime
{
    private Db db = null!;

    /// <summary>The repositories over the test database, opened empty for every test</summary>
    private MongoUnitOfWork uow = null!;

    public async ValueTask InitializeAsync()
    {
        db = await TestDatabase.OpenAsync();
        uow = new MongoUnitOfWork(db);
    }

    public async ValueTask DisposeAsync() => await db.DisposeAsync();

    [Fact]
    public async Task IsStoredAndReadBack()
    {
        var stored = await Factories.AddProductAsync(uow, 1);
        var found = await uow.Products.FindByIdAsync(stored.Id);
        Assert.NotNull(found);
        Assert.Equal(stored.Id, found.Id);
        Assert.NotNull(await uow.Products.FindBySkuAsync(stored.Sku));
    }

    [Fact]
    public async Task ListsRowsByKey()
    {
        await Factories.AddProductAsync(uow, 1);
        await Factories.AddProductAsync(uow, 2);
        var page = await uow.Products.ListAsync(0, 1);
        Assert.Equal(2, page.Total);
        Assert.Single(page.Items);
    }

    [Fact]
    public async Task StoresTheChanges()
    {
        var stored = await Factories.AddProductAsync(uow, 1);
        stored.Title = "changed";
        await uow.Products.UpdateAsync(stored);
        Assert.Equal("changed", (await uow.Products.FindByIdAsync(stored.Id))!.Title);
    }

    [Fact]
    public async Task IsDeleted()
    {
        var stored = await Factories.AddProductAsync(uow, 1);
        await uow.Products.DeleteAsync(stored);
        Assert.Null(await uow.Products.FindByIdAsync(stored.Id));
    }

    [Fact]
    public async Task AddsAndRemovesOneItemOfRelated()
    {
        var stored = await Factories.AddProductAsync(uow, 1);
        var before = stored.Related?.Count ?? 0;
        string item = 7.ToString("x24");
        var added = await uow.Products.AddRelatedAsync(stored.Id, item);
        Assert.Equal(before + 1, added!.Related!.Count);
        var removed = await uow.Products.RemoveRelatedAsync(stored.Id, item);
        Assert.Equal(before, removed!.Related!.Count);
    }
}

/// <summary>The service of the "products" table, on the in-memory repositories.</summary>
public class ProductServiceTests
{
    private readonly MemoryUnitOfWork uow = new();

    [Fact]
    public async Task CreatesAValidRow()
    {
        var service = new ProductService(uow);
        var row = Factories.NewProduct(1);
