using App;
using MongoDB.Bson;
using MongoDB.Driver;

namespace App.Tests;

/// <summary>The test database: the MongoDB database TEST_DATABASE_CONNECTION names, with every collection created empty before every test.</summary>
internal static class TestDatabase
{
    public static readonly string? Connection = Environment.GetEnvironmentVariable("TEST_DATABASE_CONNECTION");

    private static IMongoDatabase? shared;

    /// <summary>The test database, with its collections and their indexes created again.</summary>
    public static async Task<Db> OpenAsync()
    {
        if (Connection is null)
            throw new InvalidOperationException("The database tests need a disposable MongoDB database (a replica set, for its transactions): set TEST_DATABASE_CONNECTION (it is emptied)");
        var database = shared ??= Database.At(Connection);
        await database.Client.DropDatabaseAsync(database.DatabaseNamespace.DatabaseName);
        await database.CreateCollectionAsync("customers");
        await database.CreateCollectionAsync("products");
        await database.CreateCollectionAsync("orders");
        await database.CreateCollectionAsync("countries");
        await database.GetCollection<BsonDocument>("customers").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["email"] = 1 }, new CreateIndexOptions { Unique = true }));
        await database.GetCollection<BsonDocument>("products").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["sku"] = 1 }, new CreateIndexOptions { Unique = true }));
        await database.GetCollection<BsonDocument>("products").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["title"] = 1 }));
        await database.GetCollection<BsonDocument>("orders").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["year"] = 1, ["number"] = 1 }, new CreateIndexOptions { Unique = true }));
        await database.GetCollection<BsonDocument>("orders").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["customer"] = 1 }));
        await database.GetCollection<BsonDocument>("countries").Indexes.CreateOneAsync(new CreateIndexModel<BsonDocument>(new BsonDocument { ["id"] = 1 }, new CreateIndexOptions { Unique = true }));
        return new Db(database);
    }
}
